const topAssetsHourly = `-- name: TopAssetsHourly :many
SELECT h.asset_id, a.title, sum(h.views)::bigint AS views, sum(h.watch_seconds)::bigint AS watch_seconds,
    sum(h.bytes)::bigint AS bytes
FROM playback_hourly h
JOIN assets a ON a.id = h.asset_id AND a.project_id = h.project_id AND a.status <> 'deleted'
WHERE h.project_id = $1 AND h.hour >= $2 AND h.hour < $3
    AND ($4::text IS NULL OR h.app_id = $4)
GROUP BY h.asset_id, a.title
HAVING sum(h.views) > 0
ORDER BY sum(h.views) DESC, h.asset_id
LIMIT 10
`

type TopAssetsHourlyParams struct {
	ProjectID string
	Start     pgtype.Timestamptz
	Stop      pgtype.Timestamptz
	AppID     pgtype.Text
}

type TopAssetsHourlyRow struct {
	AssetID      string
	Title        pgtype.Text
	Views        int64
	WatchSeconds int64
	Bytes        int64
}

// The most viewed live assets in a 24-hour range.
func (q *Queries) TopAssetsHourly(ctx context.Context, arg TopAssetsHourlyParams) ([]TopAssetsHourlyRow, error) {
	rows, err := q.db.Query(ctx, topAssetsHourly,
		arg.ProjectID,
		arg.Start,
		arg.Stop,
		arg.AppID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TopAssetsHourlyRow{}
	for rows.Next() {
		var i TopAssetsHourlyRow
		if err := rows.Scan(
			&i.AssetID,
			&i.Title,
			&i.Views,
			&i.WatchSeconds,
			&i.Bytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
